scripts.樵夫对话.txt:
// 路人对话：指路

	If ($Event == 370) @Event370; 
	If ($Event == 420) @Event420;

	Say("樵夫：青山相待，白云相爱。梦不到紫罗袍共黄金带。一茅斋，野花开，管甚谁家兴废谁成败？陋巷单瓢亦乐哉。贫，气不改！达，志不改！", 0);
	Return;	
	
@Event370:
	If ($Talkmap064 == 0) @Talk0;
	If ($Talkmap064 == 1) @Talk1;
	If ($Talkmap064 == 2) @Talk2;
	If ($Talkmap064 == 3) @Talk3;
  
@Talk0:
	Say("樵夫：城池俱坏，英雄安在？云龙几度相交代？想兴衰，苦为怀。唐家才起隋家败，世态有如云变改。功，也不久长！名，也不久长！", 0);
	Assign($Talkmap064, 1);
	Return;
  
@Talk1:	
	Say("樵夫：峰峦如聚，波涛如怒，山河表里潼关路。望西都，意踟蹰。伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦！亡，百姓苦！", 0);
	Assign($Talkmap064, 2);
	Return;
	
@Talk2:	
	Say("独孤剑：好词！", 2);
	Say("张琳心：妙曲！", 21);
	Say("樵夫：哈哈哈哈，二位是要上少林吗？", 0);
	Say("独孤剑：不错。", 2);
	Say("樵夫：哦，少林寺有很多举世无双的武功绝学，你们可不能枉走一趟啊。无虚大师虽然身在佛门，却急公好义，你们若是有缘得到无虚大师指点一二，那就终身受用不尽了。", 0);
	Say("独孤剑：多谢指点。", 2);
	Say("樵夫：往北走很快就到少林寺了，东边的路口是通往朱仙镇的。", 0);
	Assign($Talkmap064, 3);
	Return;	
	
@Talk3:	
	Say("樵夫：青山相待，白云相爱。梦不到紫罗袍共黄金带。一茅斋，野花开，管甚谁家兴废谁成败？陋巷单瓢亦乐哉。贫，气不改！达，志不改！", 0);
	Return;	
	
@Event420:	
	Say("樵夫：看来两位的少林之行获益匪浅，真是可喜可贺呀。");
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 370) @Event370;
	If ($Event == 420) @Event420;
	
	Return;
	
@Event370:
	If ($Talkmap064 <> 0) @Talk;
	Say("张琳心：少室山虽然没有华山那么险峻，但是清幽古朴，确是一处清修的好地方。", 21);
	Return;
@Talk:	
	Say("张琳心：我看那樵夫应该是一个隐居的高士，这少室山上果然藏龙卧虎啊！", 21);
	Return;
	
@Event420:	
	Say("张琳心：独孤哥哥，我们这次上少林，收获可真是不小啊。", 21);
	Say("独孤剑：是啊，无虚大师为人胸襟广阔，少林绝技又精妙绝伦，难怪天下武林都以少林为尊。", 1);
	Return;

traps.trap01.txt:
//切换到map065少林寺

	If ($Event >= 420) @Event420;

	FadeOut();
	StopMusic();
	PlayMusic("禅音.mp3");
	SaveNpc();
	SaveObj();
	LoadMap("map065_少林寺.map");
	LoadNpc("map065.npc");
	LoadObj("map065.obj");
	SetPlayerPos(2, 79);
	SetPlayerDir(5);
	FadeIn();
	Return;
	
@Event420:
	Say("张琳心：独孤哥哥，我们不是刚从少林寺下来吗？", 21);
	Return;

traps.trap02.txt:
//切换到map070朱仙镇

	If ($Event << 420) @Eventless420;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map070_朱仙镇西北.map");
	LoadNpc("map070.npc");
	LoadObj("map070.obj");
	SetPlayerPos(4, 7);
	SetPlayerDir(7);
	FadeIn();
	Return;
	
@Eventless420:
	Say("张琳心：独孤哥哥，我们先上少林要紧。", 21);
	Return;
